export {
  detectUiLocale,
  formatUiLanguageOptionLabel,
  getTranslatedUiLocale,
  isRtlUiLocale,
  listSupportedUiLanguageOptions,
  normalizeUiLanguageSetting,
  resolveUiLocale,
  type TranslatedUiLocale,
  type UiLanguageSetting,
  type UiLocale,
} from "../ui-language.js";

import { getTranslatedUiLocale, type UiLocale } from "../ui-language.js";

export function getBrowserUiLanguage(): string {
  try {
    return chrome.i18n?.getUILanguage?.() ?? navigator.language ?? "en";
  } catch {
    return navigator.language ?? "en";
  }
}

