type WidenStrings<T> = T extends (...args: infer Args) => infer Result
  ? (...args: Args) => Result
  : T extends string
    ? string
    : T extends object
      ? { readonly [K in keyof T]: WidenStrings<T[K]> }
      : T;

type UiStrings = WidenStrings<typeof UI_STRINGS.en>;
type DeepPartial<T> = {
  [K in keyof T]?: T[K] extends (...args: never[]) => unknown
    ? T[K]
    : T[K] extends object
      ? DeepPartial<T[K]>
      : T[K];
};

