const DYNAMIC_UI_STRING_TEMPLATE_KEYS = [
  "status.voiceReconnecting",
  "status.noMatchFor",
  "status.duplicateFile",
  "status.fileTooLarge",
  "status.skillArchiveInstalled",
  "status.imageFolderOpened",
  "status.logFolderOpened",
  "status.rateLimitUsed",
  "status.browserActionFailedWithReason",
  "status.selectedCount",
  "status.itemCount",
  "prompts.imageAttachmentPromptExtract",
  "prompts.imageAttachmentDescribe",
  "profileEditor.recommendationPlaceholder",
] as const;

type DynamicUiStringTemplateKey = (typeof DYNAMIC_UI_STRING_TEMPLATE_KEYS)[number];
type UiStringTranslationStats = {
  totalStaticStrings: number;
  translatedStaticStrings: number;
  missingStaticKeys: string[];
};

export function getUiStrings(locale: UiLocale | string | undefined): UiStrings {
  const translatedLocale = getTranslatedUiLocale(locale);
  return mergeUiStrings(
    mergeUiStrings(
      mergeUiStrings(UI_STRINGS.en, buildGeneratedUiStringOverride(translatedLocale)),
      buildCoreLocaleOverride(translatedLocale),
    ),
    RICH_UI_STRINGS_BY_LOCALE[translatedLocale] ?? {},
  );
}

export function getUiStringTranslationStats(locale: UiLocale | string | undefined): UiStringTranslationStats {
  const translatedLocale = getTranslatedUiLocale(locale);
  const totalStaticStrings = STATIC_UI_STRING_TRANSLATION_KEYS.length;
  if (translatedLocale === "en" || translatedLocale === "ko") {
    return {
      totalStaticStrings,
      translatedStaticStrings: totalStaticStrings,
      missingStaticKeys: [],
    };
  }

  const generated = GENERATED_UI_STRING_TRANSLATIONS[translatedLocale] ?? {};
  const missingStaticKeys = STATIC_UI_STRING_TRANSLATION_KEYS.filter((key) => !generated[key]?.trim());
  return {
    totalStaticStrings,
    translatedStaticStrings: totalStaticStrings - missingStaticKeys.length,
    missingStaticKeys,
  };
}

export function listStaticUiStringTranslationKeys(): string[] {
  return [...STATIC_UI_STRING_TRANSLATION_KEYS];
}

export function listDynamicUiStringTemplateKeys(): DynamicUiStringTemplateKey[] {
  return [...DYNAMIC_UI_STRING_TEMPLATE_KEYS];
}

function core(
  assistant: string,
  settings: string,
  language: string,
  profile: string,
  model: string,
  voice: string,
  newChat: string,
  send: string,
  save: string,
  search: string,
  refresh: string,
  cancel: string,
  startChat: string,
  backToChat: string,
  composerPlaceholder: string,
  historyPlaceholder: string,
): CoreLocaleText {
  return {
    assistant,
    settings,
    language,
    profile,
    model,
    voice,
    newChat,
    send,
    save,
    search,
    refresh,
    cancel,
    startChat,
    backToChat,
    composerPlaceholder,
    historyPlaceholder,
  };
}

function buildCoreLocaleOverride(locale: UiLocale): DeepPartial<UiStrings> {
  const text = CORE_LOCALE_TEXT[locale];
  if (!text) {
    return {};
  }
  return {
    panelTitleSide: text.assistant,
    usageNotice: {
      startCta: text.startChat,
    },
    newChat: text.newChat,
    labels: {
      settings: text.settings,
      language: text.language,
      profile: text.profile,
      model: text.model,
      voice: text.voice,
    },
    actions: {
      send: text.send,
      save: text.save,
      search: text.search,
      refresh: text.refresh,
      cancelEdit: text.cancel,
    },
    settings: {
      uiLanguage: text.language,
      uiTheme: "Theme",
      themeSystem: "System",
      themeDark: "Dark",
      themeLight: "Light",
    },
    settingsPanel: {
      backToChat: text.backToChat,
      themeDescription: "Follow system appearance or choose a fixed theme.",
    },
    profileEditor: {
      name: text.profile,
      instructions: text.settings,
    },
    composerPlaceholder: text.composerPlaceholder,
    historyPlaceholder: text.historyPlaceholder,
  };
}

const OPTIONAL_ENGLISH_FALLBACK_STATIC_UI_STRING_KEYS = new Set<string>([
  "actionCards.selection-fact-check",
  "actions.createProfileDirect",
  "actions.disconnectApiKey",
  "labels.audio",
  "realtimeInterpreter.costGuideBody",
  "realtimeInterpreter.costGuideRate",
  "realtimeInterpreter.costGuideTitle",
  "realtimeInterpreter.off",
  "realtimeInterpreter.on",
  "realtimeInterpreter.outputVolume",
  "realtimeInterpreter.outputVolumeHelp",
  "realtimeInterpreter.start",
  "settings.imagePromptHoverButton",
  "settingsPanel.imagePromptHoverButtonDescription",
  "status.apiKeyConnected",
  "status.apiKeyDisconnected",
  "status.turnSteerExpired",
  "prompts.onlineImageContextLabel",
  "prompts.onlineImageAltLabel",
  "prompts.onlineImagePageTitleLabel",
  "prompts.onlineImagePageUrlLabel",
]);
const STATIC_UI_STRING_TRANSLATION_KEYS = collectStaticUiStringKeys(UI_STRINGS.en).filter(
  (key) => !OPTIONAL_ENGLISH_FALLBACK_STATIC_UI_STRING_KEYS.has(key),
);
const GENERATED_TRANSLATION_MARKER_PATTERN = /@@\s*\d+@@?/u;
const GENERATED_TRANSLATION_MARKER_REPLACE_PATTERN = /@@\s*\d+@@?/gu;
const NON_TRANSLATABLE_STATIC_UI_STRING_KEYS = new Set<string>(["onboarding.sourceInstallCommand"]);

function buildGeneratedUiStringOverride(locale: UiLocale): DeepPartial<UiStrings> {
  const messages = GENERATED_UI_STRING_TRANSLATIONS[locale];
  if (!messages) {
    return {};
  }

  const override: Record<string, unknown> = {};
  for (const key of STATIC_UI_STRING_TRANSLATION_KEYS) {
    const value = normalizeGeneratedUiStringValue(key, messages[key]);
    if (value?.trim()) {
      setNestedUiStringValue(override, key, value);
    }
  }

  const dynamicOverride = buildGeneratedDynamicUiStringOverride(messages);
  return mergeUiStrings(override, dynamicOverride) as DeepPartial<UiStrings>;
}

function normalizeGeneratedUiStringValue(key: string, value: string | undefined): string | undefined {
  const englishValue = getStaticEnglishUiStringValue(key);
  if (NON_TRANSLATABLE_STATIC_UI_STRING_KEYS.has(key)) {
    return englishValue ?? value;
  }
  if (value && GENERATED_TRANSLATION_MARKER_PATTERN.test(value)) {
    return englishValue ?? value.replaceAll(GENERATED_TRANSLATION_MARKER_REPLACE_PATTERN, "").trim();
  }
  return value;
}

function getStaticEnglishUiStringValue(key: string): string | undefined {
  const value = key.split(".").reduce<unknown>((current, part) => {
    if (!current || typeof current !== "object") {
      return undefined;
    }
    return (current as Record<string, unknown>)[part];
  }, UI_STRINGS.en);
  return typeof value === "string" ? value : undefined;
}

function buildGeneratedDynamicUiStringOverride(messages: Record<string, string>): DeepPartial<UiStrings> {
  const template = (key: DynamicUiStringTemplateKey): string | undefined => messages[key]?.trim() || undefined;
  return {
    status: {
      voiceReconnecting: (attempt: number, maxAttempts: number) =>
        formatGeneratedTemplate(template("status.voiceReconnecting"), {
          attempt: String(Math.max(1, Math.floor(attempt))),
          maxAttempts: String(Math.max(Math.max(1, Math.floor(attempt)), Math.floor(maxAttempts))),
        }) ?? UI_STRINGS.en.status.voiceReconnecting(attempt, maxAttempts),
      noMatchFor: (query: string) =>
        formatGeneratedTemplate(template("status.noMatchFor"), { query }) ?? UI_STRINGS.en.status.noMatchFor(query),
      duplicateFile: (name: string) =>
        formatGeneratedTemplate(template("status.duplicateFile"), { name }) ?? UI_STRINGS.en.status.duplicateFile(name),
      fileTooLarge: (name: string) =>
        formatGeneratedTemplate(template("status.fileTooLarge"), { name }) ?? UI_STRINGS.en.status.fileTooLarge(name),
      skillArchiveInstalled: (count: number) =>
        formatGeneratedTemplate(template("status.skillArchiveInstalled"), { count: String(count) }) ??
        UI_STRINGS.en.status.skillArchiveInstalled(count),
      imageFolderOpened: (folder: string) =>
        formatGeneratedTemplate(template("status.imageFolderOpened"), { folder }) ??
        UI_STRINGS.en.status.imageFolderOpened(folder),
      logFolderOpened: (folder: string) =>
        formatGeneratedTemplate(template("status.logFolderOpened"), { folder }) ??
        UI_STRINGS.en.status.logFolderOpened(folder),
      rateLimitUsed: (limitName: string, usedPercent: number, reset: string) =>
        formatGeneratedTemplate(template("status.rateLimitUsed"), {
          limitName,
          usedPercent: String(Math.round(usedPercent)),
          reset,
        }) ?? UI_STRINGS.en.status.rateLimitUsed(limitName, usedPercent, reset),
      browserActionFailedWithReason: (reason: string) =>
        formatGeneratedTemplate(template("status.browserActionFailedWithReason"), { reason }) ??
        UI_STRINGS.en.status.browserActionFailedWithReason(reason),
      selectedCount: (count: number) =>
        formatGeneratedTemplate(template("status.selectedCount"), { count: String(count) }) ??
        UI_STRINGS.en.status.selectedCount(count),
      itemCount: (count: number, label: string) =>
        formatGeneratedTemplate(template("status.itemCount"), { count: String(count), label }) ??
        UI_STRINGS.en.status.itemCount(count, label),
    },
    prompts: {
      imageAttachmentPromptExtract: (imageList: string, imageCount: number, outputLanguage: string) =>
        formatGeneratedTemplate(template("prompts.imageAttachmentPromptExtract"), {
          imageList,
          imageCount: String(imageCount),
          pluralSuffix: imageCount > 1 ? "s" : "",
          outputLanguage,
        }) ?? UI_STRINGS.en.prompts.imageAttachmentPromptExtract(imageList, imageCount, outputLanguage),
      imageAttachmentDescribe: (imageList: string, imageCount: number, outputLanguage: string) =>
        formatGeneratedTemplate(template("prompts.imageAttachmentDescribe"), {
          imageList,
          imageCount: String(imageCount),
          pluralSuffix: imageCount > 1 ? "s" : "",
          outputLanguage,
        }) ?? UI_STRINGS.en.prompts.imageAttachmentDescribe(imageList, imageCount, outputLanguage),
    },
    profileEditor: {
      recommendationPlaceholder: (index: number) =>
        formatGeneratedTemplate(template("profileEditor.recommendationPlaceholder"), { index: String(index) }) ??
        UI_STRINGS.en.profileEditor.recommendationPlaceholder(index),
    },
  };
}

function formatGeneratedTemplate(template: string | undefined, values: Record<string, string>): string | null {
  if (!template) {
    return null;
  }
  const formatted = Object.entries(values).reduce(
    (result, [key, value]) => result.replaceAll(`{${key}}`, value),
    template,
  );
  return /\{[A-Za-z][A-Za-z0-9]*\}/u.test(formatted) ? null : formatted;
}

function collectStaticUiStringKeys(value: unknown, prefix = ""): string[] {
  if (typeof value === "string") {
    return value.trim() ? [prefix] : [];
  }
  if (!isPlainObject(value)) {
    return [];
  }

  return Object.entries(value).flatMap(([key, child]) => {
    const path = prefix ? `${prefix}.${key}` : key;
    return collectStaticUiStringKeys(child, path);
  });
}

function setNestedUiStringValue(target: Record<string, unknown>, path: string, value: string): void {
  const parts = path.split(".");
  let cursor: Record<string, unknown> = target;
  for (const [index, part] of parts.entries()) {
    if (index === parts.length - 1) {
      cursor[part] = value;
      return;
    }
    const next = cursor[part];
    if (!isPlainObject(next)) {
      cursor[part] = {};
    }
    cursor = cursor[part] as Record<string, unknown>;
  }
}

function mergeUiStrings<T extends Record<string, unknown>>(base: T, override: DeepPartial<T>): T {
  const merged: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(override)) {
    if (value === undefined) {
      continue;
    }
    const baseValue = merged[key];
    merged[key] =
      isPlainObject(baseValue) && isPlainObject(value)
        ? mergeUiStrings(baseValue as Record<string, unknown>, value as Record<string, unknown>)
        : value;
  }
  return merged as T;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}
